const AGES={y:{n:"若年層"},m:{n:"ミドル層"},s:{n:"シニア層"}};
const HHS={1:{n:"単身世帯"},2:{n:"夫婦世帯"},3:{n:"ファミリー世帯"}};
const TIERS={
  a:{n:"マス層",tint:"var(--mass)",soft:"var(--mass-soft)",hex:"#7CAE93"},
  b:{n:"アッパーマス層",tint:"var(--upper)",soft:"var(--upper-soft)",hex:"#E0A05F"},
  c:{n:"富裕層",tint:"var(--wealth)",soft:"var(--wealth-soft)",hex:"#B489C4"}
};
const CAT=[["ins","保険"],["loan","ローン"],["inv","投資・資産形成"],["pay","決済・ポイント"],["etc","その他（信託・税務）"]];

function classify(age,assets){
  const ageKey = age<40 ? "y" : age<60 ? "m" : "s";
  const tierKey = assets<3000 ? "a" : assets<10000 ? "b" : "c";
  return {ageKey,tierKey};
}

function fmtAsset(v){
  return v>=10000 ? (v/10000).toFixed(v%10000===0?0:1)+"億円" : v.toLocaleString("ja-JP")+"万円";
}

